		case NORM_Y:
			v0 = getCorner(2);
			v1 = getCorner(3);
			v2 = getCorner(7);
			v3 = getCorner(6);
			break;
		case NORM_Z:
			v0 = getCorner(1);
			v1 = getCorner(5);
			v2 = getCorner(7);
			v3 = getCorner(3);
