        root = NULL;
    }
}

void CRobloxTreeCtrl::OnGetDispInfo(NMHDR* notify, LRESULT* result)
{
    NMTVDISPINFO* info = reinterpret_cast<NMTVDISPINFO*>(notify);
    reinterpret_cast<CRobloxTreeCtrlNode*>(info->item.lParam)->onGetDispInfo(info);
    *result = 0;
}

